@Composable fun DeviceModeSelectionScreen(onMode: (DeviceMode) -> Unit) { SetupFrame { Text("¿Cómo se va a utilizar este dispositivo?", color = Color.White, fontSize = 28.sp, fontWeight = FontWeight.Bold); Text("Elegí una opción para preparar Moderá.", color = Color(0xFFCBD5E1)); Spacer(Modifier.height(24.dp)); ModeCard("🧒", "Dispositivo del niño", "Configurar perfil, permisos y vista infantil") { onMode(DeviceMode.CHILD) }; ModeCard("👤", "Dispositivo del adulto", "Consultar perfiles infantiles vinculados") { onMode(DeviceMode.ADULT) } } }

@Composable fun AdultEmailScreen(state: AdultAuthUiState, onEmail: (String) -> Unit, onContinue: () -> Unit) { SetupFrame { SetupHeader("Accedé a Moderá", "Usá tu correo electrónico para acceder a los perfiles que tengas vinculados."); Spacer(Modifier.height(24.dp)); OutlinedTextField(state.email, onEmail, Modifier.fillMaxWidth(), label = { Text("Correo electrónico") }, placeholder = { Text("nombre@correo.com") }, singleLine = true, isError = state.emailError, supportingText = if (state.emailError) ({ Text("Ingresá un correo electrónico válido.") }) else null, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email), colors = setupTextFieldColors()); state.errorMessage?.let { Text(it, color = MaterialTheme.colorScheme.error, fontSize = 13.sp) }; Spacer(Modifier.height(18.dp)); SetupButton("Continuar", !state.loading, onContinue) } }

@Composable fun AdultVerificationScreen(state: AdultAuthUiState, onCode: (String) -> Unit, onVerify: () -> Unit, onBack: () -> Unit) { SetupFrame { TextButton(onBack, contentPadding = PaddingValues(0.dp)) { Text("← Volver", color = Color(0xFFCBD5E1)) }; SetupHeader("Revisá tu correo", "Enviamos un código de verificación a\n${state.email}"); state.devCode?.let { Text("DEBUG · código: $it", color = AppColors.PurpleSoft, fontSize = 13.sp, modifier = Modifier.padding(top = 12.dp)) }; Spacer(Modifier.height(24.dp)); CodeField(state.code, onCode, "Código de 6 dígitos", state.codeError); if (state.codeError) Text("El código ingresado no es válido.", color = MaterialTheme.colorScheme.error, fontSize = 13.sp); state.errorMessage?.let { Text(it, color = MaterialTheme.colorScheme.error, fontSize = 13.sp) }; Spacer(Modifier.height(18.dp)); SetupButton("Verificar", state.code.length == 6 && !state.loading, onVerify) } }

@Composable fun AdultLinkProfileScreen(state: LinkDeviceUiState, onCode: (String) -> Unit, onFind: () -> Unit, onConfirm: () -> Unit, onOpen: (com.juan.habitos.domain.model.Profile) -> Unit) { SetupFrame(scroll = true) { SetupHeader("Perfiles infantiles", "Elegí un perfil vinculado o agregá uno nuevo."); Spacer(Modifier.height(22.dp)); if (state.loaded && state.profiles.isEmpty()) Text("Todavía no tenés perfiles vinculados.", color = Color(0xFFCBD5E1)); state.profiles.forEach { profile -> Surface(onClick = { onOpen(profile) }, Modifier.fillMaxWidth().padding(bottom = 10.dp), color = AppColors.Card, shape = RoundedCornerShape(16.dp), border = BorderStroke(1.dp, AppColors.Divider)) { Row(Modifier.padding(16.dp), verticalAlignment = Alignment.CenterVertically) { Text(profile.avatar, fontSize = 36.sp); Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { Text(profile.name, color = Color.White, fontWeight = FontWeight.Bold); Text("${profile.age} años", color = Color(0xFFCBD5E1), fontSize = 13.sp) }; Text("Abrir ›", color = AppColors.PurpleSoft, fontWeight = FontWeight.Bold) } } }; Spacer(Modifier.height(18.dp)); Text("Vincular perfil infantil", color = Color.White, fontSize = 20.sp, fontWeight = FontWeight.Bold); Text("Ingresá el código ADULT_PROFILE_LINK generado desde el dispositivo infantil.", color = Color(0xFFCBD5E1), fontSize = 13.sp); Spacer(Modifier.height(14.dp)); CodeField(state.code, onCode, "Código de vinculación", state.errorMessage != null); state.errorMessage?.let { Text(it, color = MaterialTheme.colorScheme.error, fontSize = 13.sp) }; Spacer(Modifier.height(14.dp)); if (state.foundProfile == null) SetupButton("Vincular", state.code.length == 6 && !state.loading, onFind); state.foundProfile?.let { profile -> Card(colors = CardDefaults.cardColors(containerColor = AppColors.Card), border = BorderStroke(1.dp, AppColors.PurpleSoft), shape = RoundedCornerShape(18.dp)) { Column(Modifier.fillMaxWidth().padding(20.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp)) { Text("Perfil vinculado", color = AppColors.PurpleSoft, fontWeight = FontWeight.Bold); Text(profile.avatar, fontSize = 50.sp); Text(profile.name, color = Color.White, fontSize = 21.sp, fontWeight = FontWeight.Bold); Text("${profile.age} años", color = Color(0xFFCBD5E1)); Spacer(Modifier.height(6.dp)); SetupButton("Entrar al panel", true, onConfirm) } } }; Spacer(Modifier.height(20.dp)); Surface(color = AppColors.Card, shape = RoundedCornerShape(14.dp)) { Column(Modifier.padding(16.dp)) { Text("¿Dónde encuentro el código?", color = Color.White, fontWeight = FontWeight.Bold); Text("En el dispositivo infantil, abrí el panel adulto y elegí ‘Vincular a un adulto responsable’.", color = Color(0xFFCBD5E1), fontSize = 13.sp, lineHeight = 19.sp) } } } }

@Composable fun AdultProfileLinkCodeScreen(state: AdultProfileLinkCodeUiState, onRetry: () -> Unit, onBack: () -> Unit) { SetupFrame { TextButton(onBack, contentPadding = PaddingValues(0.dp)) { Text("← Volver", color = Color(0xFFCBD5E1)) }; SetupHeader("Vinculá a un adulto responsable", "Ingresá este código en el dispositivo del adulto."); Spacer(Modifier.height(28.dp)); if (state.loading) CircularProgressIndicator(color = AppColors.PurpleSoft); state.code?.let { code -> Text("Código de vinculación", color = Color(0xFFCBD5E1)); Text(code.chunked(3).joinToString(" "), color = Color.White, fontSize = 40.sp, fontWeight = FontWeight.Bold, letterSpacing = 7.sp); state.validForMinutes?.let { Text("Válido por aproximadamente $it minutos", color = AppColors.PurpleSoft, fontWeight = FontWeight.Bold) } }; state.errorMessage?.let { Text(it, color = MaterialTheme.colorScheme.error); Spacer(Modifier.height(14.dp)); SetupButton("Reintentar", true, onRetry) } } }

@Composable private fun SetupFrame(scroll: Boolean = false, content: @Composable ColumnScope.() -> Unit) { val modifier = Modifier.fillMaxSize().background(AppColors.Surface).statusBarsPadding().navigationBarsPadding().padding(24.dp).let { if (scroll) it.verticalScroll(rememberScrollState()) else it }; Column(modifier, verticalArrangement = if (scroll) Arrangement.Top else Arrangement.Center, content = content) }
@Composable private fun SetupHeader(title: String, subtitle: String) { Text(title, color = Color.White, fontSize = 28.sp, fontWeight = FontWeight.Bold); Spacer(Modifier.height(10.dp)); Text(subtitle, color = Color(0xFFCBD5E1), lineHeight = 22.sp) }
@Composable private fun ModeCard(icon: String, title: String, subtitle: String, onClick: () -> Unit) { Surface(onClick = onClick, Modifier.fillMaxWidth().padding(bottom = 14.dp), color = AppColors.Card, shape = RoundedCornerShape(18.dp), border = BorderStroke(1.dp, AppColors.Divider)) { Row(Modifier.padding(18.dp), verticalAlignment = Alignment.CenterVertically) { Text(icon, fontSize = 34.sp); Spacer(Modifier.width(14.dp)); Column(Modifier.weight(1f)) { Text(title, color = Color.White, fontWeight = FontWeight.Bold, fontSize = 17.sp); Text(subtitle, color = Color(0xFF94A3B8), fontSize = 13.sp) }; Text("›", color = AppColors.PurpleSoft, fontSize = 28.sp) } } }
@Composable private fun CodeField(value: String, onValue: (String) -> Unit, label: String, error: Boolean) { OutlinedTextField(value, onValue, Modifier.fillMaxWidth(), label = { Text(label) }, placeholder = { Text("_  _  _  _  _  _") }, singleLine = true, isError = error, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.NumberPassword), textStyle = LocalTextStyle.current.copy(fontSize = 23.sp, letterSpacing = 8.sp, fontWeight = FontWeight.Bold), colors = setupTextFieldColors()) }
@Composable private fun SetupButton(text: String, enabled: Boolean, onClick: () -> Unit) { Button(onClick, Modifier.fillMaxWidth().height(54.dp), enabled = enabled, colors = ButtonDefaults.buttonColors(containerColor = AppColors.Purple), shape = RoundedCornerShape(14.dp)) { Text(text, fontWeight = FontWeight.Bold) } }
@Composable private fun setupTextFieldColors() = OutlinedTextFieldDefaults.colors(focusedTextColor = Color.White, unfocusedTextColor = Color.White, focusedBorderColor = AppColors.PurpleSoft, unfocusedBorderColor = AppColors.Divider, focusedLabelColor = AppColors.PurpleSoft, unfocusedLabelColor = Color(0xFF94A3B8), cursorColor = AppColors.PurpleSoft, errorSupportingTextColor = MaterialTheme.colorScheme.error)
